function escText(value='') {
  const map = {'€':'\\200','“':'\\223','”':'\\224','–':'-','—':'-','’':"'",'á':'\\341','à':'\\340','â':'\\342','ã':'\\343','ç':'\\347','é':'\\351','ê':'\\352','í':'\\355','ó':'\\363','ô':'\\364','õ':'\\365','ú':'\\372','Á':'\\301','É':'\\311','Í':'\\315','Ó':'\\323','Ú':'\\332','Ç':'\\307'};
  return String(value).replace(/[\\()]/g, '\\$&').replace(/[€“”–—’áàâãçéêíóôõúÁÉÍÓÚÇ]/g, c => map[c] || c).replace(/[^\x20-\x7e\\]/g,'?');
}
function rgb(c){ return c.map(v=>(v/255).toFixed(3)).join(' '); }
function wrap(text, max){
  const words=String(text||'').split(/\s+/); const lines=[]; let line='';
  for(const word of words){ const next=line?line+' '+word:word; if(next.length>max && line){lines.push(line);line=word;}else line=next; }
  if(line) lines.push(line); return lines;
}
class Pdf {
  constructor(){this.objects=[null];this.pages=[];this.fonts={};this.images={};}
  obj(s=''){this.objects.push(s);return this.objects.length-1;}
  set(id,s){this.objects[id]=s;}
  font(name,base){this.fonts[name]=this.obj(`<< /Type /Font /Subtype /Type1 /BaseFont /${base} /Encoding /WinAnsiEncoding >>`);}
  jpeg(name,b64,width,height){const binary=atob(b64);this.images[name]=this.obj(`<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${binary.length} >>\nstream\n${binary}\nendstream`);}
  page(draw){this.pages.push(draw.join('\n'));}
  build(){
    const catalog=this.obj(), pagesRoot=this.obj(); const pageIds=[];
    for(const stream of this.pages){const content=this.obj(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);const pid=this.obj();pageIds.push(pid);this.set(pid,`<< /Type /Page /Parent ${pagesRoot} 0 R /MediaBox [0 0 ${A4[0]} ${A4[1]}] /Resources << /Font << ${Object.entries(this.fonts).map(([k,v])=>`/${k} ${v} 0 R`).join(' ')} >> /XObject << ${Object.entries(this.images).map(([k,v])=>`/${k} ${v} 0 R`).join(' ')} >> >> /Contents ${content} 0 R >>`);}
    this.set(pagesRoot,`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`);
    this.set(catalog,`<< /Type /Catalog /Pages ${pagesRoot} 0 R >>`);
    let out='%PDF-1.4\n%\xE2\xE3\xCF\xD3\n'; const offsets=[0];
    for(let i=1;i<this.objects.length;i++){offsets[i]=out.length;out+=`${i} 0 obj\n${this.objects[i]}\nendobj\n`;}
    const xref=out.length;out+=`xref\n0 ${this.objects.length}\n0000000000 65535 f \n`;
    for(let i=1;i<this.objects.length;i++) out+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
    out+=`trailer\n<< /Size ${this.objects.length} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;
    return Uint8Array.from(out, c=>c.charCodeAt(0)&255);
  }
}
function rect(cmd,x,y,w,h,c){cmd.push(`${rgb(c)} rg ${x} ${y} ${w} ${h} re f`);}
function line(cmd,x1,y1,x2,y2,c,w=.8){cmd.push(`${rgb(c)} RG ${w} w ${x1} ${y1} m ${x2} ${y2} l S`);}
function text(cmd,str,x,y,size=10,font='F1',c=BRAND.navy){cmd.push(`BT /${font} ${size} Tf ${rgb(c)} rg 1 0 0 1 ${x} ${y} Tm (${escText(str)}) Tj ET`);}
function imagePdf(cmd,name,x,y,w,h){cmd.push(`q ${w} 0 0 ${h} ${x} ${y} cm /${name} Do Q`);}
function polygon(cmd,points,stroke=BRAND.gold,fill=null,w=.8){if(!points.length)return;let p=`${points[0][0]} ${points[0][1]} m `;for(let i=1;i<points.length;i++)p+=`${points[i][0]} ${points[i][1]} l `;p+='h ';if(fill)p+=`${rgb(fill)} rg `;p+=`${rgb(stroke)} RG ${w} w ${fill?'B':'S'}`;cmd.push(p);}
function para(cmd,str,x,y,width,size=10,leading=14,font='F1',c=BRAND.grey){const max=Math.max(18,Math.floor(width/(size*.52)));for(const l of wrap(str,max)){text(cmd,l,x,y,size,font,c);y-=leading;}return y;}
