function cleanReport(body={}){
  const pillars=Array.isArray(body.pillars)?body.pillars.slice(0,10):[];
  const applicable=Math.max(0,Number(body.completion?.applicable)||0), answered=Math.max(0,Number(body.completion?.answered)||0);
  const scopes=(Array.isArray(body.scopes)?body.scopes:[]).slice(0,8).map(String);
  const recommendations=(Array.isArray(body.recommendations)?body.recommendations:[]).slice(0,8).map((r,i)=>typeof r==='string'?{priority:i<2?'Alta':'Média',action:r,impact:'Operacional',effort:'Médio',horizon:i<2?'30 dias':'90 dias'}:{priority:String(r.priority||'Média'),action:String(r.action||r.text||''),impact:String(r.impact||'Operacional'),effort:String(r.effort||'Médio'),horizon:String(r.horizon||'90 dias')});
  return {
    name:String(body.name||'Cliente Privus').slice(0,80), company:String(body.company||'Organização').slice(0,100),
    date:String(body.date||new Intl.DateTimeFormat('pt-PT').format(new Date())).slice(0,30),
    level:String(body.level||'Nível 3 - Estruturado').slice(0,80), score:Math.max(0,Math.min(100,Number(body.score)||0)),
    summary:String(body.summary||'A organização apresenta bases de conformidade já definidas, mas ainda existem lacunas entre capacidade, execução e evidência que limitam a maturidade regulatória global.').slice(0,1200),
    pillars:pillars.length?pillars:[{name:'Governação',score:64},{name:'Liderança',score:58},{name:'Cultura',score:47},{name:'Pessoas',score:55},{name:'Processos',score:61},{name:'Tecnologia',score:72},{name:'Evidência',score:49},{name:'Resiliência',score:44},{name:'Sustentabilidade',score:52},{name:'Confiança',score:68}],
    risks:(Array.isArray(body.risks)?body.risks:[]).slice(0,5).map(String), strengths:(Array.isArray(body.strengths)?body.strengths:[]).slice(0,5).map(String),
    recommendations, scopes:scopes.length?scopes:['RGPD','AI Act','ISO 27001','ISO 22301','ISO 37301'],
    completion:{answered,applicable,complete:applicable>0&&answered>=applicable},
    gates:(Array.isArray(body.gates)?body.gates:[]).slice(0,5).map(String),
    roadmap:body.roadmap&&typeof body.roadmap==='object'?body.roadmap:{}, reference:String(body.reference||crypto.randomUUID().slice(0,8).toUpperCase()).slice(0,30), version:String(body.version||'PRIA v1.1').slice(0,30),
  };
}
