function bytesToBase64(bytes){let s='';for(let i=0;i<bytes.length;i+=0x8000)s+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(s);}
function json(data,status=200,extra={}){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8',...extra}});}
function cors(request,env){const origin=request.headers.get('Origin')||'';if(!origin)return '';const ownOrigin=new URL(request.url).origin;if(origin===ownOrigin)return origin;const allowed=String(env.ALLOWED_ORIGIN||'').split(',').map(s=>s.trim()).filter(Boolean);return allowed.includes(origin)?origin:'';}
async function graphToken(env){const body=new URLSearchParams({client_id:env.MS_CLIENT_ID,client_secret:env.MS_CLIENT_SECRET,scope:'https://graph.microsoft.com/.default',grant_type:'client_credentials'});const r=await fetch(`https://login.microsoftonline.com/${env.MS_TENANT_ID}/oauth2/v2.0/token`,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw new Error('Falha de autenticação Microsoft 365');return (await r.json()).access_token;}
async function sendMail(env,to,subject,html,pdfBytes){const token=await graphToken(env);const payload={message:{subject,body:{contentType:'HTML',content:html},toRecipients:[{emailAddress:{address:to}}],attachments:[{'@odata.type':'#microsoft.graph.fileAttachment',name:'Relatorio-Executivo-PRIA.pdf',contentType:'application/pdf',contentBytes:bytesToBase64(pdfBytes)}]},saveToSentItems:true};const r=await fetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(env.MS_SENDER)}/sendMail`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('Falha no envio do email');}

