const page=`<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PRIA · Relatório Executivo</title><style>:root{--n:#0D1B2A;--g:#C8A96E;--c:#F0EBE0}*{box-sizing:border-box}body{margin:0;background:var(--c);color:var(--n);font-family:Arial,sans-serif}.wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.card{max-width:720px;background:white;padding:48px;border-top:5px solid var(--g);box-shadow:0 20px 60px #0d1b2a18}.ey{color:#947747;font-size:12px;letter-spacing:.16em;font-weight:bold}h1{font-family:Georgia,serif;font-weight:400;font-size:48px;line-height:1.05;margin:18px 0}p{color:#5A5346;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:28px 0}.k{background:var(--n);color:white;padding:18px}.k b{color:var(--g);display:block;font-size:12px;margin-bottom:8px}button{border:0;background:var(--g);color:var(--n);font-weight:bold;padding:15px 22px;cursor:pointer}small{display:block;margin-top:18px;color:#777}@media(max-width:600px){.card{padding:28px}h1{font-size:36px}.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><section class="card"><div class="ey">PRIVUS KUZOLA · PRIA</div><h1>Relatório Executivo profissional</h1><p>Protótipo funcional do PDF que será enviado automaticamente ao cliente após a conclusão da avaliação.</p><div class="grid"><div class="k"><b>DOCUMENTO</b>6 páginas A4</div><div class="k"><b>INTEGRIDADE</b>Completo, rastreável e metodologicamente limitado</div></div><button id="download">Gerar PDF de demonstração</button><small>Os dados apresentados são fictícios e servem apenas para validar o formato.</small></section></main><script>document.querySelector('#download').onclick=async()=>{const b=document.querySelector('#download');b.disabled=true;b.textContent='A gerar…';try{const r=await fetch('/api/report',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mode:'preview',report:${JSON.stringify(sample)}})});if(!r.ok)throw 0;const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Relatorio-Executivo-PRIA.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert('Não foi possível gerar o PDF.')}finally{b.disabled=false;b.textContent='Gerar PDF de demonstração'}}</script></body></html>`;

export default {async fetch(request,env){const url=new URL(request.url);if(request.method==='OPTIONS'){const o=cors(request,env);return new Response(null,{status:o?204:403,headers:o?{'access-control-allow-origin':o,'access-control-allow-methods':'POST, OPTIONS','access-control-allow-headers':'content-type'}:{}});}if(url.pathname!=='/api/report'){if(env.ASSETS)return env.ASSETS.fetch(request);return new Response('Not found',{status:404});}if(request.method!=='POST')return new Response('Method not allowed',{status:405});const origin=cors(request,env);if(request.headers.get('Origin')&&!origin)return json({error:'Origem não autorizada'},403);let body;try{body=await request.json();}catch{return json({error:'Pedido inválido'},400);}const report=cleanReport(body.report||body);if(body.mode!=='preview'&&!report.completion.complete)return json({error:'O relatório só pode ser emitido depois de respondidas todas as perguntas aplicáveis.',completion:report.completion},422,origin?{'access-control-allow-origin':origin}:{});const pdf=createReportPdf(report);if(body.mode==='preview')return new Response(pdf,{headers:{'content-type':'application/pdf','content-disposition':'attachment; filename="Relatorio-Executivo-PRIA.pdf"',...(origin?{'access-control-allow-origin':origin}:{})}});if(!body.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email))return json({error:'Email inválido'},400);const missing=['MS_TENANT_ID','MS_CLIENT_ID','MS_CLIENT_SECRET','MS_SENDER'].filter(name=>!env[name]);if(missing.length)return json({error:`Serviço de email ainda não configurado: ${missing.join(', ')}`,missing},503);const html=`<p>Olá ${escText(report.name)},</p><p>Segue em anexo o Relatório Executivo do PRIA da ${escText(report.company)}.</p><p><strong>${escText(report.level)} · ${Math.round(report.score)}/100</strong></p><p>O relatório resulta das respostas fornecidas e distingue o cálculo determinístico da respetiva interpretação. A validação documental pode alterar as conclusões qualitativas e as prioridades.</p><p>Privus Kuzola<br>contacto@privuskuzola.pt</p>`;try{await sendMail(env,body.email,`Relatório Executivo PRIA · ${report.company}`,html,pdf);if(env.INTERNAL_RECIPIENT&&env.INTERNAL_RECIPIENT!==body.email)await sendMail(env,env.INTERNAL_RECIPIENT,`Cópia PRIA · ${report.company}`,html,pdf);return json({ok:true,reference:report.reference},200,origin?{'access-control-allow-origin':origin}:{})}catch(e){return json({error:'Não foi possível enviar o relatório'},502,origin?{'access-control-allow-origin':origin}:{})}}};
